/**
 * Run `convert` with configured options-field bridge support.
 *
 * Returns an owned `ConversionResult` handle on success, or zero on failure. Check
 * `htm_last_error_code` / `htm_last_error_context` for error details. Free
 * the returned handle with `htm_conversion_result_free`.
 *
 * If a bridge was attached to `options`, it is cloned into the core call.
 *
 * # Safety
 *
 * String pointers must be valid and NUL-terminated for the duration of this call.
 */
HTMAlefHandle htm_convert(const char *html,
                          HTMAlefHandle options);

/**
 * Attach a vtable visitor bridge to a `ConversionOptions` options handle.
 *
 * The `HtmVisitor` encapsulates C callbacks invoked during conversion. Neither handle
 * is consumed; both must be freed independently after every conversion using the options
 * handle has completed. Pass `visitor = 0` to clear a previously attached visitor.
 *
 * # Safety
 *
 * `options` must be a live handle returned by `htm_conversion_options_from_json`
 * or an equivalent constructor. `visitor` must be zero or a live handle returned by
 * `htm_visitor_create`. The visitor handle must remain live while the options handle
 * can be used for conversion.
 */
void htm_options_set_visitor(HTMAlefHandle options,
                             HTMAlefHandle visitor);

/**
 * Create a new visitor handle from a callbacks struct.
 *
 * The returned handle must be freed with `htm_visitor_free`.
 * The `HtmVisitorCallbacks` struct is **copied** into the handle;
 * the caller may free it after this call returns.
 *
 * Returns null on allocation failure.
 *
 * # Safety
 *
 * `callbacks` must point to a valid, fully initialised `HtmVisitorCallbacks`.
 * `user_data` (embedded in the struct) must remain valid and accessible from
 * any thread that calls `htm_convert_with_visitor` until after
 * `htm_visitor_free` is called.
 */
HTMAlefHandle htm_visitor_create(const struct HTMHtmVisitorCallbacks *callbacks);

/**
 * Free a visitor handle previously returned by `htm_visitor_create`.
 *
 * After this call the pointer is invalid and must not be used.
 *
 * # Safety
 *
 * `visitor` must have been returned by `htm_visitor_create`, or be null.
 * Passing a null pointer is safe and has no effect.
 */
void htm_visitor_free(HTMAlefHandle visitor);

